      "id": "faceplace-08",
      "title": "Children’s Wellbeing Online",
      "reviewedTitle": "Children’s Wellbeing Online",
      "form": "human-reviewed reading",
      "paragraphs": [
        "Excerpts from two UK government reports about young people and social media.",
        "The first report describes why some young people value social media.",
        "For some young people, especially those living in rural areas or who belong to a cultural, faith or interest group that's hard to find people for locally, social media is described as the main way they can connect with people who shared their interests or experiences. Going out costs money that not everyone has. Social media, for many, is free social infrastructure.",
        "It then turns to algorithms and public popularity counts.",
        "Younger children said they felt like they didn't have much control over what the algorithm showed them, and some described being unable to stop seeing things they didn't want to see, even after indicating they weren't interested. Older teenagers said they had learned to manage their feed better but they still found the design problematic.",
        "Likes and follower counts were described as tools for competition rather than genuine connection. Younger children cared more about likes and follower counts themselves than older teens did. Several young people mentioned appreciating the option on some platforms to hide how many likes a post gets because it removed the pressure to compete.",
        "The second report says the relationship is complex and not always negative.",
        "Thus, when thinking about interventions, it will be important to isolate the elements, behaviours, and personal dispositions that have been found to be harmful. For example, the fact that users are currently not in control of the content they are exposed to may need to be considered when thinking about interventions.",
        "While this chapter details the more negative aspects of social media usage, our participants also gave ample examples of when social media had been beneficial to them. For example, it allows people to connect to niche communities of like-minded individuals, which can feel empowering and positive. Interventions should consider how to leverage these more positive elements of social media, for example, the sense of connection and shared purpose."
      ],
